import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split('\n')
    idx = 0
    while idx < len(input_data) and not input_data[idx].strip():
        idx += 1
    if idx >= len(input_data):
        return

    parts = input_data[idx].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])
    idx += 1

    pictures = []
    for _ in range(k + 1):
        while idx < len(input_data) and not input_data[idx].strip(): # Skip empty lines before picture
            idx += 1
        pic = []
        for r in range(n):
            if idx < len(input_data):
                pic.append(list(input_data[idx]))
                idx += 1
        pictures.append(pic)

    def count_diffs(p1, p2):
        cnt = 0
        for r in range(n):
            for c in range(m):
                if p1[r][c] != p2[r][c]:
                    cnt += 1
        return cnt

    def can_recolor(p, r, c):
        if r == 0 or r == n - 1 or c == 0 or c == m - 1:
            return False
        val = p[r][c]
        neighbors = [p[r-1][c], p[r+1][c], p[r][c-1], p[r][c+1]]
        target = '1' if val == '0' else '0'
        return all(x == target for x in neighbors)

    def apply_recolor(p, r, c):
        new_p = [row[:] for row in p]
        new_p[r][c] = '1' if new_p[r][c] == '0' else '0'
        return new_p

    def find_path(start_pic, target_pic):
        if start_pic == target_pic:
            return []

        queue = deque([(start_pic, [])])
        visited = {tuple(tuple(row) for row in start_pic)}

        while queue:
            curr, path = queue.popleft()

            for r in range(1, n - 1):
                for c in range(1, m - 1):
                    if can_recolor(curr, r, c):
                        nxt = apply_recolor(curr, r, c)
                        nxt_tuple = tuple(tuple(row) for row in nxt)

                        if nxt == target_pic:
                            return path + [(r + 1, c + 1)]

                        if nxt_tuple not in visited:
                            visited.add(nxt_tuple)
                            queue.append((nxt, path + [(r + 1, c + 1)]))

        return None

    best_start = -1
    min_ops = float('inf')

    for i in range(k + 1):
        total_ops = 0
        possible = True
        used = [False] * (k + 1)
        used[i] = True

        current_state = pictures[i]
        ops = []

        unassigned = set(range(k + 1))
        unassigned.remove(i)

        while unassigned:
            found_next = False
            for j in unassigned:
                target = pictures[j]
                if current_state == target:
                    path = []
                else:
                    path = find_path(current_state, target)

                if path is not None:
                    total_ops += len(path)
                    ops.extend(path)
                    ops.append(('copy', j + 1))
                    unassigned.remove(j)
                    current_state = target
                    found_next = True
                    break

            if not found_next:
                possible = False
                break

        if possible and total_ops < min_ops:
            min_ops = total_ops
            best_start = i
            best_ops = ops

    print(best_start + 1)
    print(len(best_ops))
    for op in best_ops:
        if op[0] == 'copy':
            print(f"2 {op[1]}")
